create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'customer' check(role in ('customer','admin')), created_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', price numeric(10,2) not null check(price>=0), compare_at_price numeric(10,2), category_id uuid references public.categories(id), featured boolean not null default false, bestseller boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, url text not null, alt_text text not null default '', position int not null default 0);
create table if not exists public.product_variants(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, size text not null, color text not null default '', stock int not null default 0 check(stock>=0), sku text unique, unique(product_id,size,color));
create table if not exists public.user_addresses(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, recipient text not null, phone text not null, address text not null, city text not null, state text not null, pin text not null, is_default boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.carts(id uuid primary key default gen_random_uuid(), user_id uuid unique references public.profiles(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.cart_items(id uuid primary key default gen_random_uuid(), cart_id uuid not null references public.carts(id) on delete cascade, variant_id uuid not null references public.product_variants(id), quantity int not null check(quantity between 1 and 10), unique(cart_id,variant_id));
create table if not exists public.coupons(id uuid primary key default gen_random_uuid(), code text not null unique, discount_type text not null check(discount_type in ('percent','fixed')), discount_value numeric(10,2) not null check(discount_value>0), minimum_order numeric(10,2) not null default 0, active boolean not null default true, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id), order_number text not null unique default ('RG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), customer_name text not null, email text not null, phone text not null, shipping_address jsonb not null, subtotal numeric(10,2) not null check(subtotal>=0), shipping numeric(10,2) not null default 0 check(shipping>=0), discount numeric(10,2) not null default 0 check(discount>=0), total numeric(10,2) not null check(total>=0), status text not null default 'pending' check(status in ('pending','confirmed','packed','shipped','delivered','cancelled','refunded')), payment_status text not null default 'unpaid' check(payment_status in ('unpaid','pending','paid','failed','refunded')), created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), variant_id uuid references public.product_variants(id), product_name text not null, size text not null, unit_price numeric(10,2) not null check(unit_price>=0), quantity int not null check(quantity between 1 and 10));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), provider text not null, provider_order_id text, provider_payment_id text, amount numeric(10,2) not null, status text not null default 'created', created_at timestamptz not null default now());
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rating int not null check(rating between 1 and 5), title text, body text, approved boolean not null default false, created_at timestamptz not null default now(), unique(product_id,user_id));
create index if not exists products_active_created_idx on public.products(active,created_at desc); create index if not exists variants_product_idx on public.product_variants(product_id); create index if not exists orders_user_created_idx on public.orders(user_id,created_at desc); create index if not exists order_items_order_idx on public.order_items(order_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.user_addresses enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.product_variants enable row level security; alter table public.carts enable row level security; alter table public.cart_items enable row level security; alter table public.coupons enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.reviews enable row level security;
create policy "profile read own or admin" on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy "profile update own" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role='customer');
create policy "public read categories" on public.categories for select using(true); create policy "admin manage categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public read active products" on public.products for select using(active or public.is_admin()); create policy "admin manage products" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "public read product images" on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and p.active) or public.is_admin()); create policy "admin manage product images" on public.product_images for all using(public.is_admin()) with check(public.is_admin());
create policy "public read variants" on public.product_variants for select using(exists(select 1 from public.products p where p.id=product_id and p.active) or public.is_admin()); create policy "admin manage variants" on public.product_variants for all using(public.is_admin()) with check(public.is_admin());
create policy "addresses own" on public.user_addresses for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "cart own" on public.carts for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "cart items via own cart" on public.cart_items for all using(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid()) or public.is_admin()) with check(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid()) or public.is_admin());
create policy "active coupons public read" on public.coupons for select using(active); create policy "admin manage coupons" on public.coupons for all using(public.is_admin()) with check(public.is_admin());
create policy "orders own read" on public.orders for select using(user_id=auth.uid() or public.is_admin()); create policy "admin manage orders" on public.orders for all using(public.is_admin()) with check(public.is_admin()); create policy "order items own read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin()))); create policy "admin manage order items" on public.order_items for all using(public.is_admin()) with check(public.is_admin()); create policy "admin payments only" on public.payments for all using(public.is_admin()) with check(public.is_admin());
create policy "approved reviews public" on public.reviews for select using(approved or user_id=auth.uid() or public.is_admin()); create policy "customer submit review" on public.reviews for insert with check(user_id=auth.uid() and approved=false); create policy "admin manage reviews" on public.reviews for all using(public.is_admin()) with check(public.is_admin());
